package it.jarviswake

/** Static command explanations; never the entire section or values from the phone. */
internal object MenuCommandHelp {
    fun text(label:String):String = when(label) {
        "Appunti locali", "Apri appunti locali" -> "Apre l’elenco degli appunti salvati sul telefono. Puoi leggerli, crearli, aggiornarli o eliminarli con conferma, anche senza rete."
        "Aggiorna appunti" -> "Rilegge l’archivio del telefono e aggiorna tutti i pulsanti degli appunti. Non crea né modifica appunti."
        "Nuovo appunto" -> "Apre un appunto vuoto. Scrivi titolo e testo, poi Salva appunto. Indietro abbandona la bozza senza creare un record."
        "Salva appunto" -> "Salva titolo e testo dell’appunto aperto. Se è stato modificato altrove devi rileggerlo; in caso di esito incerto verifica l’elenco prima di riprovare."
        "Elimina appunto" -> "Chiede conferma prima di cancellare soltanto questo appunto dal telefono. Annulla lo conserva. Non rimuove copie già presenti nelle chat."
        "Parla con Jarvis" -> "Avvia il ciclo vocale usando la modalità ChatGPT e il progetto configurati. Prima verifica i permessi e il collegamento necessari."
        "Avvia ascolto Hey Jarvis" -> "Richiede l’avvio dell’ascolto locale della parola Hey Jarvis. Servono i permessi Android; durante ChatGPT Voice la cattura wake resta sospesa."
        "Ferma ascolto" -> "Ferma volontariamente il riconoscimento della parola wake. Per riabilitarlo usa Avvia ascolto Hey Jarvis."
        "Configurazione" -> "Apre le categorie delle preferenze di JarvisWake. Puoi scegliere una categoria o seguire la configurazione guidata."
        "Servizio" -> "Apre gli strumenti di supporto e manutenzione, separati dall’utilizzo quotidiano."
        "Configurazione guidata" -> "Attraversa le sei categorie di configurazione e il riepilogo. Non ripristina le preferenze già salvate."
        "Permessi e assistente" -> "Apre i comandi per microfono, notifiche, Accessibilità, cover e ruolo Assistente. Le autorizzazioni si concedono nei pannelli Android."
        "ChatGPT e progetto" -> "Apre la scelta tra app ChatGPT e WebView, il collegamento al progetto e le prove di apertura."
        "Voce e saluto" -> "Apre il campo della frase richiesta all’avvio di Voice. Puoi modificarla, salvarla o ripristinare il testo predefinito."
        "Audio di avvio" -> "Apre file audio di attesa, interruttore, volume e tempo minimo prima del comando Voice."
        "Cover" -> "Apre la scelta dell’opacità iniziale e l’accesso alla guida dei gesti della cover."
        "Collegamento e azioni" -> "Apre le categorie di abbinamento al plugin, azioni del telefono e consenso separato per gli appunti."
        "Diagnostica", "Esporta diagnostica" -> "Permette di salvare uno ZIP diagnostico nella destinazione scelta. Non include audio, contenuto degli appunti o testo generico delle conversazioni."
        "Manutenzione WebView" -> "Apre i comandi per cache e dati della sola WebView. La rimozione dei dati richiede conferma e può richiedere un nuovo accesso."
        "Autorizza microfono e notifiche" -> "Richiede soltanto i permessi microfono e notifiche mancanti tramite Android. Non avvia una chiamata."
        "Imposta Jarvis come assistente" -> "Richiede i permessi necessari e apre la scelta dell’assistente digitale predefinito in Android."
        "Abilita automazione Voice" -> "Apre Accessibilità di Android per abilitare il servizio JarvisWake che interagisce con Voice. Devi effettuare tu la scelta."
        "Consenti cover sopra le altre app" -> "Apre l’autorizzazione Android che permette di mostrare la cover Jarvis sopra le altre applicazioni."
        "Permessi Android e batteria" -> "Apre le informazioni Android di JarvisWake per controllare autorizzazioni e impostazioni batteria."
        "Salva frase" -> "Salva il testo del campo Frase del saluto, comprese le righe. Salvare la preferenza non prova che ChatGPT abbia pronunciato il saluto."
        "Ripristina «ciao jarvis»" -> "Sostituisce la frase del saluto salvata con il valore predefinito ciao jarvis."
        "Seleziona collegamento e nome progetto" -> "Permette di scegliere lo shortcut creato da ChatGPT e di confermare il nome esatto del progetto, inclusi gli spazi."
        "Prova collegamento senza Voice" -> "Apre il progetto tramite lo shortcut scelto, senza premere Voice o iniziare una chiamata."
        "Salva indirizzo ChatGPT" -> "Salva l’indirizzo valido compilato per la WebView. Il prossimo ciclo userà quell’indirizzo."
        "Apri accesso a ChatGPT" -> "Apre ChatGPT nella modalità selezionata per controllare l’accesso con il tuo account."
        "Imposta modello e livello in ChatGPT" -> "Mostra le impostazioni ChatGPT usando il percorso già configurato. Modello e livello si scelgono nell’interfaccia ChatGPT."
        "Scegli audio di attesa" -> "Apre il selettore Android per scegliere il file audio privato usato durante l’attesa di Voice."
        "Guida ai gesti" -> "Apre l’argomento della guida che descrive le zone e le azioni dei gesti sulla cover."
        "Svuota cache WebView" -> "Elimina le risorse temporanee della WebView e ricarica ChatGPT. Non elimina gli appunti locali."
        "Elimina dati locali ChatGPT" -> "Chiede conferma prima di eliminare cache, cookie e dati dei siti nella WebView. Potresti dover accedere di nuovo; non cancella le chat dell’account."
        "Gestisci abbinamento ChatGPT", "Abbinamento e stato" -> "Apre la gestione del collegamento privato con JarvisWake Link e dello stato dell’abbinamento."
        "Maps, chiamate e WhatsApp" -> "Apre il consenso per le azioni del telefono e i relativi permessi. Entrare qui non esegue una chiamata, un messaggio o una navigazione."
        "Accesso agli appunti dal plugin", "Appunti e accesso dal plugin" -> "Apre il consenso separato per leggere, creare e aggiornare appunti tramite ChatGPT. Le letture richieste passano nella conversazione."
        "Apri pagina privata di collegamento" -> "Apre nel browser la pagina privata dello stesso JarvisWake Link per creare il codice di abbinamento."
        "Incolla codice di collegamento" -> "Apre il campo protetto in cui incollare il codice dalla pagina privata. Non incollarlo nelle chat."
        "Cancella collegamento dal telefono" -> "Chiede conferma per rimuovere il codice di abbinamento dal telefono. Gli appunti hanno un archivio separato e restano conservati."
        "Autorizza rubrica e chiamate" -> "Richiede ad Android l’accesso ai contatti, alle chiamate e allo stato telefonico per le azioni autorizzate del plugin."
        "Guida alle azioni e ai plugin" -> "Apre la guida delle azioni disponibili tramite JarvisWake Link e dei loro limiti."
        "Guida alla memoria e alla rilettura" -> "Apre la guida sugli appunti locali, sul consenso remoto e sulle istruzioni facoltative di rilettura."
        "Guida completa", "Guida completa e plugin" -> "Apre la guida completa di JarvisWake, con indice e ricerca per argomento o domanda."
        "Cerca" -> "Cerca le parole o la domanda scritte nel campo della guida e mostra gli argomenti pertinenti."
        "Tutti gli argomenti" -> "Cancella il filtro della ricerca e mostra l’intero indice della guida."
        "Indice e ricerca" -> "Torna dall’argomento aperto all’indice e alla ricerca della guida."
        "Esporta guida completa" -> "Apre il selettore documento per salvare la guida completa come file Markdown. Contiene istruzioni statiche, non dati del telefono."
        "Avanti" -> "Passa alla categoria successiva della configurazione guidata, salvando una frase o un indirizzo validi se presenti. Non avvia prove Voice o azioni del telefono."
        "Termina" -> "Conclude il riepilogo della configurazione e torna all’uso quotidiano."
        "Indietro" -> "Torna alla schermata precedente. Nell’editor appunti abbandona le modifiche non salvate e riapre l’elenco."
        else -> "Apre la voce «$label»."
    }
}
